import com.learningspace.WidgetStore;import com.learningspace.WidgetMetrics;import java.time.*;import org.json.*;
public class WidgetMetricsCheck {
 static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception{JSONObject j=WidgetStore.validate(WidgetStoreCheck.sample().toString());WidgetMetrics m=WidgetMetrics.from(j,Instant.parse("2026-10-15T12:00:00Z"));check(m.minutes==12&&m.streak==3&&m.weekMinutes==84&&m.weekDays==7,"Real snapshot counts");check(m.percent()==26,"Progress ratio");m=WidgetMetrics.from(j,Instant.parse("2026-10-15T18:31:00Z"));check(m.minutes==0&&m.streak==3,"Local midnight rollover preserves yesterday’s streak");m=WidgetMetrics.from(j,Instant.parse("2026-10-17T12:00:00Z"));check(m.minutes==0&&m.streak==0&&m.weekMinutes==60,"Gap resets streak and rolls week");m=WidgetMetrics.from(j,Instant.parse("2026-10-25T12:00:00Z"));check(m.weekMinutes==0&&m.weekDays==0,"Old weeks do not remain current");j.put("todayDone",false);m=WidgetMetrics.from(j,Instant.parse("2026-10-16T12:00:00Z"));check(m.streak==0,"Unqualified snapshot day does not earn a streak");m=WidgetMetrics.from(new JSONObject(),Instant.parse("2026-10-16T12:00:00Z"));check(m.minutes==0&&m.streak==0&&m.goal==45&&m.encouragement.length()>0,"First launch stays honest and supportive");j=WidgetStoreCheck.sample().put("todayMinutes",120);m=WidgetMetrics.from(j,Instant.parse("2026-10-15T12:00:00Z"));check(m.percent()==100&&m.minutes==120,"Ring caps without hiding actual time");check(WidgetStore.validate(j.toString()).getString("themePreference").equals("system"),"Old snapshot theme default");j.put("themePreference","dark");check(WidgetStore.validate(j.toString()).getString("themePreference").equals("dark"),"Theme retained");System.out.println("Native widget metrics passed: real counts, calendar rollover, streak gaps, rolling week, empty data, capped ring, and themes.");}
}
